static const int sheet_frames[BODY_CLIP_COUNT] = {
    1, 8, 8, 4, 5, 2, 2, 1,
};

/* [body_sheet_frames] Devolve quantos quadros o clip tem. Fora da faixa, devolve 0. */
int body_sheet_frames(int clip)
{
    if (clip < 0 || clip >= BODY_CLIP_COUNT) {
        return 0;
    }
    return sheet_frames[clip];
}

/* [body_sheet_rows] Devolve as 16 linhas 1bpp da layer do quadro. Fora da faixa, devolve 0. */
const uint16_t *body_sheet_rows(int clip, int frame, int layer)
{
    int base;
    int i;

    if (clip < 0 || clip >= BODY_CLIP_COUNT || layer < 0 || layer >= BODY_LAYER_COUNT) {
        return 0;
    }
    if (frame < 0 || frame >= sheet_frames[clip]) {
        return 0;
    }
    base = 0;
    for (i = 0; i < clip; i++) {
        base += sheet_frames[i];
    }
    base += frame;
    return sheet_rows + (base * BODY_LAYER_COUNT + layer) * BODY_SHEET_H;
}
